def f(x):
    return x**3 - 12 * x

def fprime(x):
    return 3 * x**2 - 12

def describe(a, b):
    print(f"on ({a}, {b}): f({a}) = {f(a)}, f({b}) = {f(b)}")
    inside = []
    for c in [-2, 2]:
        if a < c < b:
            inside.append(c)
    if inside:
        print(f"  critical number {inside} is inside, so f' changes sign: neither")
        return
    m = (a + b) / 2
    print(f"  no critical number inside, so test the midpoint: f'({m}) = {fprime(m)}")
    if fprime(m) > 0:
        print("  f' > 0 on the whole interval: increasing")
    else:
        print("  f' < 0 on the whole interval: decreasing")

describe(2, 5)
describe(-2, 2)
describe(0, 3)
describe(-5, -3)
describe(-1, 1)

