def f(x):
    return x**3 - 12 * x

n = int(input())
for problem in range(n):
    a = int(input())
    b = int(input())
    print(f"on ({a}, {b}): f({a}) = {f(a)}, f({b}) = {f(b)}")
    if a < -2 < b or a < 2 < b:
        print("  neither")
    else:
        m = (a + b) / 2
        if 3 * m**2 - 12 > 0:
            print("  increasing")
        else:
            print("  decreasing")
